/**
 * Web Crypto API AES-256-GCM Client-Side Zero-Knowledge Encryption
 * Matches the format generated by Android VaultEncryptionHelper.kt:
 * Format: "ENC:" + Base64( [12 bytes IV] + [Ciphertext + 16 bytes AuthTag] )
 */

const MASTER_SEED = "SankofaSafeVaultAES256MasterSeedKey123456789";

async function deriveKey(): Promise<CryptoKey> {
  const enc = new TextEncoder();
  const keyMaterial = enc.encode(MASTER_SEED);
  const hash = await crypto.subtle.digest("SHA-256", keyMaterial);
  return crypto.subtle.importKey(
    "raw",
    hash,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );
}

export async function encryptData(plainText: string): Promise<string> {
  if (!plainText) return "";
  try {
    const key = await deriveKey();
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const encoded = new TextEncoder().encode(plainText);

    const cipherBuffer = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv: iv },
      key,
      encoded
    );

    const combined = new Uint8Array(iv.length + cipherBuffer.byteLength);
    combined.set(iv, 0);
    combined.set(new Uint8Array(cipherBuffer), iv.length);

    let binary = "";
    for (let i = 0; i < combined.byteLength; i++) {
      binary += String.fromCharCode(combined[i]);
    }
    return "ENC:" + btoa(binary);
  } catch (error) {
    console.error("Encryption error:", error);
    return plainText;
  }
}

export async function decryptData(encryptedText: string): Promise<string> {
  if (!encryptedText || !encryptedText.startsWith("ENC:")) {
    return encryptedText;
  }
  try {
    const key = await deriveKey();
    const rawBase64 = encryptedText.replace("ENC:", "");
    const binary = atob(rawBase64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }

    if (bytes.length <= 12) return encryptedText;

    const iv = bytes.slice(0, 12);
    const cipherText = bytes.slice(12);

    const decryptedBuffer = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv: iv },
      key,
      cipherText
    );

    return new TextDecoder().decode(decryptedBuffer);
  } catch (error) {
    console.error("Decryption error:", error);
    return encryptedText;
  }
}

export async function calculateSha256(text: string): Promise<string> {
  const enc = new TextEncoder();
  const data = enc.encode(text);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
}
